  notes: [],
  activeCategoryId: '',
  activeFolder: Folder.ALL,
  activeNoteId: '',
  selectedNotesIds: [],
  searchValue: '',
  error: '',
  loading: true,
}

const noteSlice = createSlice({
  name: 'note',
  initialState,
  reducers: {
    addNote: (state, { payload }: PayloadAction<NoteItem>) => {
