        state.activeNoteId,
        state.activeCategoryId,
        state.activeFolder
      )
      state.selectedNotesIds = [
        getNewActiveNoteId(
          state.notes,
          state.activeNoteId,
          state.activeCategoryId,
          state.activeFolder
        ),
      ]
    },

